<style>
.seller-my-profile{max-width:780px;margin:0 auto;color:#34483f;font-size:13px;line-height:1.6}.seller-my-profile *{box-sizing:border-box;min-width:0}.seller-my-profile header{margin-bottom:20px}.seller-my-profile h2{font-size:25px;font-weight:600;letter-spacing:-.5px;color:#24312c;margin:0}.seller-my-profile header p{font-size:12px;color:#7b8982;margin:4px 0}.seller-my-profile .sp-card{border:1px solid #e1e8e4;border-radius:14px;background:white;padding:22px;margin-bottom:18px;scroll-margin-top:95px}.seller-my-profile h3{font-size:13px;font-weight:600;color:#24312c;margin:0 0 14px}.seller-my-profile .sp-identity{display:flex;align-items:center;gap:12px;margin-bottom:16px}.seller-my-profile .sp-identity h3{margin:0}.seller-my-profile .sp-identity p{font-size:12px;color:#7b8982;margin:2px 0;overflow-wrap:anywhere}.seller-my-profile .sp-email{background:#f7faf8;border-radius:9px;padding:11px 13px;margin:0 0 18px}.seller-my-profile dt{font-size:10px;font-weight:600;color:#839189}.seller-my-profile dd{font-size:12px;margin:3px 0 0;overflow-wrap:anywhere}.seller-my-profile .sp-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}.seller-my-profile label{display:block;font-size:12px;font-weight:500;margin:0 0 6px}.seller-my-profile input{width:100%;border:1px solid #dde6e1;border-radius:9px;background:white;padding:10px 12px;font:inherit;font-size:13px;margin:0 0 14px;color:#34483f}.seller-my-profile input:focus{outline:2px solid #1f6f5b;outline-offset:1px}.seller-my-profile [aria-invalid=true]{border-color:#b42318}.seller-my-profile button{background:#173f35;color:white;border:1px solid #173f35;border-radius:9px;padding:10px 16px;font-size:12px;font-weight:600;cursor:pointer}.seller-my-profile button:focus-visible{outline:2px solid #1f6f5b;outline-offset:3px}.seller-my-profile .sp-note{font-size:11px;color:#7b8982;margin:0 0 14px}.seller-my-profile .sp-field-error{font-size:11px;color:#b42318;margin:-8px 0 12px}.seller-my-profile .sp-errors{border